From 38fa2b89a87549c134dcb6a787b00c1eba7b0b4a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:17:03 +0100
Subject: [PATCH] greeter: keep the fingerprint reader armed while the screen
 is locked

The fingerprint reader was only armed while the lock screen UI was
shown, so touching it did nothing until the mouse was moved. Keep it
armed for as long as the screen is locked and re-arm it on timeout.

BUG: 469810
---
 greeter/pamauthenticators.cpp | 24 +++++++++++++++++++-----
 1 file changed, 19 insertions(+), 5 deletions(-)

diff --git a/greeter/pamauthenticators.cpp b/greeter/pamauthenticators.cpp
index 1d6262dd..2a4bda0a 100644
--- a/greeter/pamauthenticators.cpp
+++ b/greeter/pamauthenticators.cpp
@@ -33,6 +33,15 @@ struct PamAuthenticators::Private {
     bool hadPrompt = false;
     /*! Whether the authenticators is locked. This only turns false if any authenticator reports succeeded */
     bool locked = true;
+
+    void armFingerprintAuthenticator()
+    {
+        // The reader stays armed for as long as the screen is locked, also while the UI is hidden, so touching it
+        // unlocks without having to wake the lock screen first.
+        if (locked && !graceLocked && m_fingerprintAuthenticator && m_fingerprintAuthenticator->isAvailable()) {
+            m_fingerprintAuthenticator->tryUnlock();
+        }
+    }
 };

 PamAuthenticators::PamAuthenticators(const QString &loginName, QObject *parent)
@@ -89,10 +98,8 @@ void PamAuthenticators::startAuthenticating()
     if (PAMAuthenticatorModel::instance()->isFunctional(m_authenticator) && d->m_activeAuthenticator) {
         d->m_activeAuthenticator->tryUnlock();
     }
-    if (d->m_fingerprintAuthenticator
-        && d->m_fingerprintAuthenticator->isAvailable() /* the implicit fingerprint authenticator has no descriptor in the model */) {
-        d->m_fingerprintAuthenticator->tryUnlock();
-    }
+    // the implicit fingerprint authenticator has no descriptor in the model
+    d->armFingerprintAuthenticator();
     setState(AuthenticatorsState::Authenticating);
 }

@@ -102,7 +109,8 @@ void PamAuthenticators::stopAuthenticating()
     if (d->m_activeAuthenticator) {
         d->m_activeAuthenticator->cancel();
     }
-    if (d->m_fingerprintAuthenticator) {
+    // The fingerprint reader stays armed until the screen is unlocked
+    if (d->m_fingerprintAuthenticator && !d->locked) {
         d->m_fingerprintAuthenticator->cancel();
     }
     setState(AuthenticatorsState::Idle);
@@ -168,6 +176,11 @@ void PamAuthenticators::onAuthenticatorChanged()
         connect(d->m_fingerprintAuthenticator.get(), &PamAuthenticator::failed, this, [this] {
             qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: Non-interactive authenticator" << qUtf8Printable(d->m_fingerprintAuthenticator->service()) << "failed";
             Q_EMIT failed(d->m_fingerprintAuthenticator->authenticatorType(), d->m_fingerprintAuthenticator.get());
+            // pam_fprintd ends the conversation on its own timeout or after a rejected finger
+            d->armFingerprintAuthenticator();
+        });
+        connect(d->m_fingerprintAuthenticator.get(), &PamAuthenticator::readyChanged, this, [this] {
+            d->armFingerprintAuthenticator();
         });
         connect(d->m_fingerprintAuthenticator.get(), &PamAuthenticator::loginFailedDelayStarted, this, [this](const uint uSecDelay) noexcept -> void {
             qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: Delay started on login failure for non-interactive authenticator"
@@ -335,6 +348,7 @@ PamAuthenticator::NoninteractiveAuthenticatorTypes PamAuthenticators::authentica
 void PamAuthenticators::setGraceLocked(bool b)
 {
     d->graceLocked = b;
+    d->armFingerprintAuthenticator();
 }

 bool PamAuthenticators::hadPrompt() const
